    /* ================================ mutable byte store ================================ */

    /** Sparse byte ledger: maximal runs of stored bytes, adjacent runs merged. */
    static final class Store {
        final TreeMap<Long, byte[]> map = new TreeMap<>();
        long unique;

        /** Merges equal overlaps; returns false when an overlapping byte differs. */
        boolean put(long off, byte[] data, List<Runnable> journal) {
            if (data.length == 0) return true;
            long[] box = collect(off, data.length);
            long s = box[0];
            long e = box[1];
            ArrayList<Long> oldKeys = new ArrayList<>();
            ArrayList<byte[]> oldVals = new ArrayList<>();
            spread(oldKeys, oldVals);
            for (int i = 0; i < oldKeys.size(); i++) {
                long xs = oldKeys.get(i);
                byte[] xd = oldVals.get(i);
                long os = Math.max(xs, off);
                long oe = Math.min(xs + xd.length, off + data.length);
                if (os < oe) {
                    for (long k = os; k < oe; k++) {
                        if (xd[(int) (k - xs)] != data[(int) (k - off)]) return false;
                    }
                }
            }
            byte[] merged = new byte[(int) (e - s)];
            long oldSum = 0;
            for (int i = 0; i < oldKeys.size(); i++) {
                byte[] value = oldVals.get(i);
                oldSum += value.length;
                System.arraycopy(value, 0, merged, (int) (oldKeys.get(i) - s), value.length);
            }
            System.arraycopy(data, 0, merged, (int) (off - s), data.length);
            ArrayList<Map.Entry<Long, byte[]>> snapshot = snapshot();
            for (Long key : oldKeys) map.remove(key);
            map.put(s, merged);
            long delta = (e - s) - oldSum;
            unique += delta;
            final long ns = s;
            journal.add(
                    () -> {
                        map.clear();
                        for (Map.Entry<Long, byte[]> entry : snapshot) map.put(entry.getKey(), entry.getValue());
                        unique -= delta;
                    });
            return true;
        }

        private final ArrayList<Long> touchedKeys = new ArrayList<>();
        private final ArrayList<byte[]> touchedVals = new ArrayList<>();
        private long touchStart;
        private long touchEnd;

        /** Expands [off, off+len) over every overlapping or adjacent run, transitively. */
        private long[] collect(long off, int len) {
            touchedKeys.clear();
            touchedVals.clear();
            long s = off;
            long e = off + len;
            boolean progress = true;
            while (progress) {
                progress = false;
                Map.Entry<Long, byte[]> floor = map.floorEntry(s);
                if (floor != null) {
                    long fs = floor.getKey();
                    long fe = fs + floor.getValue().length;
                    if (fe >= s && !contains(fs)) {
                        touchedKeys.add(fs);
                        touchedVals.add(floor.getValue());
                        s = fs;
                        if (fe > e) e = fe;
                        progress = true;
                    }
                }
                Iterator<Map.Entry<Long, byte[]>> it = map.tailMap(s, true).entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<Long, byte[]> entry = it.next();
                    long start = entry.getKey();
                    if (start > e) break;
                    if (!contains(start)) {
                        touchedKeys.add(start);
                        touchedVals.add(entry.getValue());
                        long end = start + entry.getValue().length;
                        if (end > e) e = end;
                        progress = true;
                    }
                }
            }
            touchStart = s;
            touchEnd = e;
            return new long[] {s, e};
        }

        private boolean contains(long key) {
            for (int i = 0; i < touchedKeys.size(); i++) if (touchedKeys.get(i) == key) return true;
            return false;
        }

        private void spread(List<Long> keys, List<byte[]> vals) {
            keys.addAll(touchedKeys);
            vals.addAll(touchedVals);
        }

        private ArrayList<Map.Entry<Long, byte[]>> snapshot() {
            ArrayList<Map.Entry<Long, byte[]>> list = new ArrayList<>(map.size());
            for (Map.Entry<Long, byte[]> entry : map.entrySet()) list.add(entry);
            return list;
        }

        long prefix() {
            byte[] first = map.get(0L);
            return first == null ? 0 : first.length;
        }

        byte[] prefixBytes() {
            byte[] first = map.get(0L);
            return first == null ? new byte[0] : first;
        }

        List<Object> ranges() {
            List<Object> out = new ArrayList<>();
            for (Map.Entry<Long, byte[]> entry : map.entrySet()) {
                long start = entry.getKey();
                out.add(Arrays.asList(start, start + entry.getValue().length));
            }
            return out;
        }
    }

    /* ================================ merged half-open intervals ================================ */

    static final class IntervalSet {
        final TreeMap<Long, Long> map = new TreeMap<>(); // start -> exclusive end
        long count;

        void add(long a, long b, List<Runnable> journal) {
            if (b <= a) return;
            long s = a;
            long e = b;
            ArrayList<Long> oldKeys = new ArrayList<>();
            ArrayList<Long> oldEnds = new ArrayList<>();
            boolean progress = true;
            while (progress) {
                progress = false;
                Map.Entry<Long, Long> floor = map.floorEntry(s);
                if (floor != null && floor.getValue() >= s && !contains(oldKeys, floor.getKey())) {
                    oldKeys.add(floor.getKey());
                    oldEnds.add(floor.getValue());
                    s = floor.getKey();
                    if (floor.getValue() > e) e = floor.getValue();
                    progress = true;
                }
                Iterator<Map.Entry<Long, Long>> it = map.tailMap(s, true).entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<Long, Long> entry = it.next();
                    long start = entry.getKey();
                    if (start > e) break;
                    if (!contains(oldKeys, start)) {
                        oldKeys.add(start);
                        oldEnds.add(entry.getValue());
                        if (entry.getValue() > e) e = entry.getValue();
                        progress = true;
                    }
                }
            }
            long oldSum = 0;
            for (int i = 0; i < oldKeys.size(); i++) oldSum += oldEnds.get(i) - oldKeys.get(i);
            ArrayList<Map.Entry<Long, Long>> snapshot = new ArrayList<>(map.size() + 1);
            for (Map.Entry<Long, Long> entry : map.entrySet()) snapshot.add(entry);
            for (Long key : oldKeys) map.remove(key);
            map.put(s, e);
            long delta = (e - s) - oldSum;
            count += delta;
            final long ns = s;
            journal.add(
                    () -> {
                        map.clear();
                        for (Map.Entry<Long, Long> entry : snapshot) map.put(entry.getKey(), entry.getValue());
                        count -= delta;
                    });
        }

        private static boolean contains(List<Long> keys, long key) {
            for (int i = 0; i < keys.size(); i++) if (keys.get(i) == key) return true;
            return false;
        }

        List<Object> intervals() {
            List<Object> out = new ArrayList<>();
            for (Map.Entry<Long, Long> entry : map.entrySet()) out.add(Arrays.asList(entry.getKey(), entry.getValue()));
            return out;
        }

        long size() {
            return map.size();
        }

        long prefix() {
            Long end = map.get(0L);
            return end == null ? 0 : end;
        }

        byte[] hashBytes() {
            ByteArrayOutputStream out = new ByteArrayOutputStream(16 * map.size());
            for (Map.Entry<Long, Long> entry : map.entrySet()) {
                writeBE(out, entry.getKey());
                writeBE(out, entry.getValue());
            }
            return out.toByteArray();
        }
    }

    static void writeBE(ByteArrayOutputStream out, long value) {
        for (int i = 56; i >= 0; i -= 8) out.write((int) (value >>> i) & 0xff);
    }

    /* ================================ cursor ================================ */

    static final class Cur {
        final byte[] b;
        int pos;
        Cur(byte[] b) {
            this.b = b;
        }
        Cur(byte[] b, int pos) {
            this.b = b;
            this.pos = pos;
        }

        int left() {
            return b.length - pos;
        }

        private long read(int[] widthOut) {
            if (pos >= b.length) throw new Trunc("varint");
            int first = b[pos] & 0xff;
            int width = 1 << (first >> 6);
            if (left() < width) throw new Trunc("varint");
            long value = first & 0x3f;
            for (int i = 1; i < width; i++) value = (value << 8) | (b[pos + i] & 0xff);
            pos += width;
            if (widthOut != null) widthOut[0] = width;
            return value;
        }

        /** Body/header varint; overlong encodings are allowed. */
        long varint() {
            return read(null);
        }

        /** Frame type varint: must use its shortest encoding. */
        long type() {
            int[] width = new int[1];
            long value = read(width);
            if (width[0] != minWidth(value)) throw new Trunc("type");
            return value;
        }

        int u8() {
            if (pos >= b.length) throw new Trunc("byte");
            return b[pos++] & 0xff;
        }

        byte[] take(long n) {
            if (n < 0 || n > left()) throw new Trunc("bytes");
            byte[] out = Arrays.copyOfRange(b, pos, pos + (int) n);
            pos += (int) n;
            return out;
        }

        byte[] rest() {
            byte[] out = Arrays.copyOfRange(b, pos, b.length);
            pos = b.length;
            return out;
        }
    }

    static int minWidth(long value) {
        if (value < 64) return 1;
        if (value < 16384) return 2;
        if (value < (1L << 30)) return 4;
        return 8;
    }

    static byte[] vi(long value) {
        return VariableLengthIntegerEncoding.encodeVariableLengthInteger(value);
    }

    static void writeVar(ByteArrayOutputStream out, long value) {
        out.writeBytes(vi(value));
    }

    /** Closest nonnegative congruent number to expected; ties choose the larger value. */
    static long reconstruct(long raw, int width, long expected) {
        long modulus = 1L << (8 * width);
        long half = modulus >>> 1;
        long delta = Math.floorMod(raw - expected, modulus);
        long near = expected + delta;
        if (delta > half && near - modulus >= 0) return near - modulus;
        return near;
    }

    /* ================================ trace configuration ================================ */

    private long connLimit;
    private long streamLimit;
    private long clientBidiLimit;
